@@ -123,6 +123,48 @@ REVOKE CONNECT ON DATABASE template1 FROM PUBLIC;
 REVOKE CONNECT ON DATABASE finch FROM PUBLIC;
 GRANT CONNECT, TEMPORARY ON DATABASE finch TO finch_app;
 GRANT ALL PRIVILEGES ON DATABASE finch TO finch_admin;
+
+\connect finch
+BEGIN;
+-- Keep new migration bookkeeping read-only from its creation. Grant table
+-- writes individually after migrations, when the relation names are known.
+ALTER DEFAULT PRIVILEGES FOR ROLE finch_admin GRANT USAGE ON SCHEMAS TO finch_app;
+ALTER DEFAULT PRIVILEGES FOR ROLE finch_admin REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLES FROM finch_app;
+ALTER DEFAULT PRIVILEGES FOR ROLE finch_admin GRANT SELECT ON TABLES TO finch_app;
+ALTER DEFAULT PRIVILEGES FOR ROLE finch_admin GRANT USAGE, SELECT ON SEQUENCES TO finch_app;
+DO \$\$
+DECLARE
+  app_schema name;
+  app_relation record;
+BEGIN
+  FOR app_schema IN
+    SELECT nspname FROM pg_namespace
+    WHERE nspname !~ '^pg_' AND nspname <> 'information_schema'
+  LOOP
+    EXECUTE format('REVOKE CREATE ON SCHEMA %I FROM PUBLIC, finch_app', app_schema);
+    EXECUTE format('GRANT USAGE ON SCHEMA %I TO finch_app', app_schema);
+    EXECUTE format('GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA %I TO finch_app', app_schema);
+  END LOOP;
+
+  FOR app_relation IN
+    SELECT n.nspname, c.relname
+    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
+    WHERE c.relkind IN ('r', 'p', 'v', 'm', 'f')
+      AND n.nspname !~ '^pg_' AND n.nspname <> 'information_schema'
+  LOOP
+    IF app_relation.relname = 'alembic_version' THEN
+      EXECUTE format('REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE %I.%I FROM finch_app',
+                     app_relation.nspname, app_relation.relname);
+      EXECUTE format('GRANT SELECT ON TABLE %I.%I TO finch_app',
+                     app_relation.nspname, app_relation.relname);
+    ELSE
+      EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE %I.%I TO finch_app',
+                     app_relation.nspname, app_relation.relname);
+    END IF;
+  END LOOP;
+END
+\$\$;
+COMMIT;
 SQL

